/* 학습 해설
 * packing의 projection·버퍼 좌표를 u64 좌표로 이동
 * CPU의 정수와 장치의 byte 배열 사이에서 값을 옮기는 실제 구현을 읽고, 전제와 결과를 구분하는 방법을 배웁니다.
 * proj_start=(box*8+box_start)-endbit이고 proj_end=(box*8+box_end)-endbit입니다. 필드의 가장 낮은 논리 bit인 endbit를 u64 bit0으로 옮기는 계산입니다. start10,end3의 첫 box는 u64 bit7..5에, 마지막 box는 bit4..0에 해당합니다. proj_mask는 이 u64 구간을 선택하고 box_mask는 현재 byte 안 구간을 선택합니다.
 * 같은 필드를 버퍼의 절대 좌표와 u64의 상대 좌표 두 줄로 그립니다. mask가 적용되는 대상의 폭을 확인합니다. byte mask를 u64의 전체 필드 mask와 혼동하지 않습니다.
 */
int packing(void *pbuf, u64 *uval, int startbit, int endbit, size_t pbuflen,
	    enum packing_op op, u8 quirks)
{
	/* Number of bits for storing "uval"
	 * also width of the field to access in the pbuf
	 */
	u64 value_width;
	/* Logical byte indices corresponding to the
	 * start and end of the field.
	 */
	int plogical_first_u8, plogical_last_u8, box;

	/* startbit is expected to be larger than endbit */
	if (startbit < endbit)
		/* Invalid function call */
		return -EINVAL;

	value_width = startbit - endbit + 1;
	if (value_width > 64)
		return -ERANGE;

	/* Check if "uval" fits in "value_width" bits.
	 * If value_width is 64, the check will fail, but any
	 * 64-bit uval will surely fit.
	 */
	if (op == PACK && value_width < 64 && (*uval >= (1ull << value_width)))

