/* 학습 해설
 * packing LITTLE_ENDIAN·각 32bit word 안에서 byte 반전
 * CPU의 정수와 장치의 byte 배열 사이에서 값을 옮기는 실제 구현을 읽고, 전제와 결과를 구분하는 방법을 배웁니다.
 * get_le_offset은 offset/4*4로 현재 네 byte 묶음의 시작을 구합니다. 묶음 안 나머지 r을 3-r로 바꾸므로 0↔3,1↔2이고 다음 word는 4↔7,5↔6입니다. QUIRK_LITTLE_ENDIAN 하나만 선택하면 01 23 45 67 89 ab cd ef가 67 45 23 01 ef cd ab 89가 됩니다. 전체 8byte 순서를 한 번에 반전하는 것과 다릅니다.
 * 장치가 32bit word 안의 byte만 뒤집는지 전체 word 순서도 바꾸는지 문서에서 확인합니다. 이 quirk 경로의 안전한 학습 사례는 네 byte 배수 길이를 사용합니다. 이름만 보고 전체 u64 little endian으로 판단하지 않습니다.
 */
static int get_le_offset(int offset)
{
	int closest_multiple_of_4;

	closest_multiple_of_4 = (offset / 4) * 4;
	offset -= closest_multiple_of_4;
	return closest_multiple_of_4 + (3 - offset);
}

static int get_reverse_lsw32_offset(int offset, size_t len)
{
	int closest_multiple_of_4;
	int word_index;

	word_index = offset / 4;
	closest_multiple_of_4 = word_index * 4;
	offset -= closest_multiple_of_4;
	word_index = (len / 4) - word_index - 1;
	return word_index * 4 + offset;
}

static void adjust_for_msb_right_quirk(u64 *to_write, int *box_start_bit,
				       int *box_end_bit, u8 *box_mask)
{
	int box_bit_width = *box_start_bit - *box_end_bit + 1;
	int new_box_start_bit, new_box_end_bit;

