/* 학습 해설
 * Bitmap AND OR XOR·상수 한 word와 일반 경로
 * unsigned long 배열의 비트 집합을 다루는 실제 API를 읽고, 저장 표현과 유효 길이 및 사용 조건을 구분하여 배웁니다.
 * small_const_nbits이면 bitmap_and는 두 word를 AND하고 LAST_WORD_MASK를 적용한 뒤 결과가0이 아닌지 반환합니다. OR와 XOR의 작은 상수 경로는 word 연산만 수행하며 tail을 정리하지 않습니다. 일반 경로는 각 __bitmap helper로 넘어갑니다. AND의 bool은 dst 주소가 유효하다는 뜻이 아니라 유효 집합이 비어 있지 않다는 뜻입니다.
 * 교집합은 AND,합집합은 OR,서로 다른 원소는 XOR로 계산합니다. bool 반환과 저장 결과를 구분합니다. tail의 실제 숫자 대신 유효 bit를 비교하며 전체 연산의 원자성을 가정하지 않습니다.
 */
bool bitmap_and(unsigned long *dst, const unsigned long *src1,
		const unsigned long *src2, unsigned int nbits)
{
	if (small_const_nbits(nbits))
		return (*dst = *src1 & *src2 & BITMAP_LAST_WORD_MASK(nbits)) != 0;
	return __bitmap_and(dst, src1, src2, nbits);
}

