/* 학습 해설
 * Bitmap read·word 경계를 넘는 작은 필드 조회
 * unsigned long 배열의 비트 집합을 다루는 실제 API를 읽고, 저장 표현과 유효 길이 및 사용 조건을 구분하여 배웁니다.
 * nbits는1..BITS_PER_LONG의 필드 폭입니다. start의 word 번호와 내부 offset을 구하고 남은 space가 충분하면 shift와 LAST_WORD_MASK로 읽습니다. 경계를 넘으면 현재 word의 높은 조각과 다음 word의 낮은 조각을 mask 하여 offset과 space에 맞춰 합칩니다. 문서는0 또는 word 폭 초과의 반환을 undefined라고 하지만 이 원문은 조기 분기로0을 반환합니다.
 * 필드가 실제 배열 안에 있고 경계를 넘을 때 다음 word가 존재하는지 확인합니다. 문서상 유효폭을 지켜 호출합니다. 고정 버전의 invalid폭0 반환을 다른 버전의 API 보장으로 확대하지 않습니다.
 */
unsigned long bitmap_read(const unsigned long *map, unsigned long start, unsigned long nbits)
{
	size_t index = BIT_WORD(start);
	unsigned long offset = start % BITS_PER_LONG;
	unsigned long space = BITS_PER_LONG - offset;
	unsigned long value_low, value_high;

	if (unlikely(!nbits || nbits > BITS_PER_LONG))
		return 0;

	if (space >= nbits)
		return (map[index] >> offset) & BITMAP_LAST_WORD_MASK(nbits);

	value_low = map[index] & BITMAP_FIRST_WORD_MASK(start);
	value_high = map[index + 1] & BITMAP_LAST_WORD_MASK(start + nbits);
	return (value_low >> offset) | (value_high << space);
}

