/* 학습 해설
 * Bitmap write·값 폭 제한과 두 word의 바깥 bit 보존
 * unsigned long 배열의 비트 집합을 다루는 실제 API를 읽고, 저장 표현과 유효 길이 및 사용 조건을 구분하여 배웁니다.
 * 초기 guard가0 또는 word 폭 초과이면 쓰기 없이 반환합니다. 정상폭은 value에 LAST_WORD_MASK를 AND하여 높은 입력 bit를 버립니다. 한 word에 들어가면 shifted mask를 지우고 값을 OR합니다. 두 word이면 첫 word의 높은 구간과 다음 word의 낮은 구간을 나누어 clear/OR합니다. 범위 밖 bit는 산술상 보존하지만 변경 전체의 원자성은 없습니다.
 * 실제 배열 용량과 다음 word 접근을 보장합니다. 초과값을 오류로 거절해야 한다면 호출 전에 별도 숫자 검증을 수행합니다. 이 API의 truncation과 FIELD_PREP 상수 진단을 같은 계약으로 설명하지 않습니다.
 */
void bitmap_write(unsigned long *map, unsigned long value,
		  unsigned long start, unsigned long nbits)
{
	size_t index;
	unsigned long offset;
	unsigned long space;
	unsigned long mask;
	bool fit;

	if (unlikely(!nbits || nbits > BITS_PER_LONG))
		return;

	mask = BITMAP_LAST_WORD_MASK(nbits);
	value &= mask;
	offset = start % BITS_PER_LONG;
	space = BITS_PER_LONG - offset;
	fit = space >= nbits;
	index = BIT_WORD(start);

	map[index] &= (fit ? (~(mask << offset)) : ~BITMAP_FIRST_WORD_MASK(start));
	map[index] |= value << offset;
	if (fit)
		return;

	map[index + 1] &= BITMAP_FIRST_WORD_MASK(start + nbits);
	map[index + 1] |= (value >> space);

