 * Bitmap 할당 선언과 자동 정리·header와 구현의 연결
 * unsigned long 배열의 비트 집합을 다루는 실제 API를 읽고, 저장 표현과 유효 길이 및 사용 조건을 구분하여 배웁니다.
 * 헤더는 alloc,zalloc,node별 할당과 free,devm 관리형 할당을 선언하며 struct device를 전방 선언합니다. DEFINE_FREE(bitmap, unsigned long *, if (_T) bitmap_free(_T))는 cleanup 기술에 bitmap 해제를 연결합니다. 실제 메모리 할당과 실패 정리 본체는 lib/bitmap.c입니다. 선언이 있다는 사실은 자동0초기화나 소유권 이전을 모든 API에 제공하지 않습니다.
 * 0초기화가 필요하면 zalloc과 실제 flags 계약을 선택합니다. 일반free,cleanup 관리,devm 관리의 소유권을 구분하여 중복 해제를 피합니다. node는 NUMA 배치 요청이고 주소 형식의 bit 번호와 다른 개념입니다.
 */
unsigned long *bitmap_alloc(unsigned int nbits, gfp_t flags);
unsigned long *bitmap_zalloc(unsigned int nbits, gfp_t flags);
unsigned long *bitmap_alloc_node(unsigned int nbits, gfp_t flags, int node);
unsigned long *bitmap_zalloc_node(unsigned int nbits, gfp_t flags, int node);
void bitmap_free(const unsigned long *bitmap);

DEFINE_FREE(bitmap, unsigned long *, if (_T) bitmap_free(_T))

/* Managed variants of the above. */
unsigned long *devm_bitmap_alloc(struct device *dev,
				 unsigned int nbits, gfp_t flags);
unsigned long *devm_bitmap_zalloc(struct device *dev,
				  unsigned int nbits, gfp_t flags);

/*
 * lib/bitmap.c provides these functions:
 */

bool __bitmap_equal(const unsigned long *bitmap1,
		    const unsigned long *bitmap2, unsigned int nbits);
bool __pure __bitmap_or_equal(const unsigned long *src1,
			      const unsigned long *src2,
			      const unsigned long *src3,
			      unsigned int nbits);
void __bitmap_complement(unsigned long *dst, const unsigned long *src,
			 unsigned int nbits);

