/* 학습 해설
 * Bit lock 경쟁 대기·atomic 시도와 읽기 loop 분리
 * 잠금 상태의 bit 연산과 메모리 공개 순서,선점 상태를 실제 소스에서 구분하여 동시성 기술의 사용 조건을 배웁니다.
 * atomic 획득에 실패하면 preempt_enable로 대기 중 선점 가능성을 되돌립니다. 안쪽 do-while은 cpu_relax 뒤 test_bit 읽기로 bit가 풀릴 때까지 기다립니다. 그 뒤 다시 preempt_disable하고 atomic 획득을 재시도합니다. 조회가0이어도 다른 CPU가 먼저 획득할 수 있어 조회만으로 성공을 선언하지 않습니다. 계속 atomic RMW하는 bus 경쟁을 줄이는 구조입니다.
 * 외부 atomic 재시도와 내부 조회 대기를 두 단계로 그립니다. 대기 중의 preempt 변화와 성공 뒤 깊이를 추적합니다. cpu_relax를 잠금 해제나 payload 공개 barrier로 설명하지 않습니다.
 */
static inline void bit_spin_lock(int bitnum, unsigned long *addr)
{
	/*
	 * Assuming the lock is uncontended, this never enters
	 * the body of the outer loop. If it is contended, then
	 * within the inner loop a non-atomic test is used to
	 * busywait with less bus contention for a good time to
	 * attempt to acquire the lock bit.
	 */
	preempt_disable();
#if defined(CONFIG_SMP) || defined(CONFIG_DEBUG_SPINLOCK)
	while (unlikely(test_and_set_bit_lock(bitnum, addr))) {
		preempt_enable();
		do {
			cpu_relax();
		} while (test_bit(bitnum, addr));
		preempt_disable();
	}
#endif
	__acquire(bitlock);
}

/*
 * Return true if it was acquired
 */
static inline int bit_spin_trylock(int bitnum, unsigned long *addr)

