/* 학습 해설
 * Bit trylock·실패에서 preempt 깊이 복구
 * 잠금 상태의 bit 연산과 메모리 공개 순서,선점 상태를 실제 소스에서 구분하여 동시성 기술의 사용 조건을 배웁니다.
 * trylock은 먼저 preempt_disable합니다. SMP 또는 DEBUG 경로에서 이전 bit가1이면 preempt_enable하고0을 반환합니다. 성공이면 __acquire annotation 후1을 반환하며 선점 비활성 상태가 유지됩니다. 여기의1은 성공 bool이며 test_and_set_bit_lock의 이전bit0 성공과 반환 방향이 다릅니다.
 * 반환1일 때만 대응 unlock을 수행합니다. 실패 후에는 호출 전 preempt 깊이로 복구되었는지 계약을 확인합니다. 중첩 호출이 원래 깊이1이면 실패 후에도1일 수 있어 무조건0이라고 설명하지 않습니다.
 */
static inline int bit_spin_trylock(int bitnum, unsigned long *addr)
{
	preempt_disable();
#if defined(CONFIG_SMP) || defined(CONFIG_DEBUG_SPINLOCK)
	if (unlikely(test_and_set_bit_lock(bitnum, addr))) {
		preempt_enable();
		return 0;
	}
#endif
	__acquire(bitlock);
	return 1;
}

/*
 *  bit-based spin_unlock()
 */
static inline void bit_spin_unlock(int bitnum, unsigned long *addr)
{
#ifdef CONFIG_DEBUG_SPINLOCK
	BUG_ON(!test_bit(bitnum, addr));
#endif
#if defined(CONFIG_SMP) || defined(CONFIG_DEBUG_SPINLOCK)
	clear_bit_unlock(bitnum, addr);
#endif
	preempt_enable();
	__release(bitlock);

