/* 학습 해설
 * Bit unlock·release 후 preempt enable와 debug 검사
 * 잠금 상태의 bit 연산과 메모리 공개 순서,선점 상태를 실제 소스에서 구분하여 동시성 기술의 사용 조건을 배웁니다.
 * DEBUG_SPINLOCK이면 BUG_ON으로 bit가 실제 설정됐는지 검사합니다. SMP 또는 DEBUG이면 clear_bit_unlock이 release의미로 bit를 지웁니다. 그 뒤 preempt_enable과 __release annotation을 수행합니다. 정상 획득에 대응하는 해제이며 annotation 자체가 CPU 잠금 명령이나 runtime 검사인 것은 아닙니다.
 * 보호한 데이터의 변경을 마친 후 대응 unlock을 한 번 수행합니다. 미획득 또는 이중 unlock을 정상 사용법으로 만들지 않습니다. release의 데이터 공개 의미와 선점 활성화의 scheduler 의미를 구분합니다.
 */
static inline void bit_spin_unlock(int bitnum, unsigned long *addr)
{
#ifdef CONFIG_DEBUG_SPINLOCK
	BUG_ON(!test_bit(bitnum, addr));
#endif
#if defined(CONFIG_SMP) || defined(CONFIG_DEBUG_SPINLOCK)
	clear_bit_unlock(bitnum, addr);
#endif
	preempt_enable();
	__release(bitlock);
}

/*
 *  bit-based spin_unlock()
 *  non-atomic version, which can be used eg. if the bit lock itself is
 *  protecting the rest of the flags in the word.
 */
static inline void __bit_spin_unlock(int bitnum, unsigned long *addr)
{
#ifdef CONFIG_DEBUG_SPINLOCK
	BUG_ON(!test_bit(bitnum, addr));
#endif
#if defined(CONFIG_SMP) || defined(CONFIG_DEBUG_SPINLOCK)
	__clear_bit_unlock(bitnum, addr);
#endif
	preempt_enable();

