/* 학습 해설
 * Generic bit lock acquire·빠른 읽기와 atomic OR
 * 잠금 상태의 bit 연산과 메모리 공개 순서,선점 상태를 실제 소스에서 구분하여 동시성 기술의 사용 조건을 배웁니다.
 * BIT_WORD로 word 주소를 이동하고 BIT_MASK로 bit를 선택합니다. 먼저 READ_ONCE 값에 mask가 이미 있으면1을 반환하여 비싼 atomic OR를 피합니다. 없으면 raw_atomic_long_fetch_or_acquire를 실행하고 old&mask의 bool을 반환합니다. 반환0의 성공 경로에 acquire 계약이 있습니다. 첫 조회0과 atomic 이전값은 경쟁으로 달라질 수 있습니다.
 * 조회의 fast path와 실제 성공 atomic 경계를 구분합니다. 성공 acquire가 대응 release와 동기화될 때 보호 payload 읽기의 순서를 보장하는 프로토콜로 사용합니다. READ_ONCE만으로 성공 획득을 주장하지 않습니다.
 */
arch_test_and_set_bit_lock(unsigned int nr, volatile unsigned long *p)
{
	long old;
	unsigned long mask = BIT_MASK(nr);

	p += BIT_WORD(nr);
	if (READ_ONCE(*p) & mask)
		return 1;

	old = raw_atomic_long_fetch_or_acquire(mask, (atomic_long_t *)p);
	return !!(old & mask);
}


/**
 * arch_clear_bit_unlock - Clear a bit in memory, for unlock
 * @nr: the bit to set
 * @addr: the address to start counting from
 *
 * This operation is atomic and provides release barrier semantics.
 */
static __always_inline void
arch_clear_bit_unlock(unsigned int nr, volatile unsigned long *p)
{
	p += BIT_WORD(nr);
	raw_atomic_long_fetch_andnot_release(BIT_MASK(nr), (atomic_long_t *)p);

