/* 학습 해설
 * Generic clear unlock·원자적 AND NOT release
 * 잠금 상태의 bit 연산과 메모리 공개 순서,선점 상태를 실제 소스에서 구분하여 동시성 기술의 사용 조건을 배웁니다.
 * word 주소를 BIT_WORD만큼 이동한 뒤 raw_atomic_long_fetch_andnot_release에 BIT_MASK를 전달합니다. 하나의 atomic RMW로 대상 bit만 지우며 같은 word의 다른 bit를 연산 기준상 보존합니다. release의미는 보호구간의 앞선 데이터 변경을 올바른 acquire 획득자에게 공개하는 잠금 프로토콜과 연결됩니다.
 * 다른 bit도 독립 atomic writer가 변경할 수 있는 word에서는 약한 읽기/저장 대신 이 RMW 계약을 확인합니다. 보호 객체 수명과 같은 lock 사용 규칙도 지킵니다. release를 모든 뒤쪽 메모리까지 정렬하는 full barrier로 단순화하지 않습니다.
 */
arch_clear_bit_unlock(unsigned int nr, volatile unsigned long *p)
{
	p += BIT_WORD(nr);
	raw_atomic_long_fetch_andnot_release(BIT_MASK(nr), (atomic_long_t *)p);
}

/**
 * arch___clear_bit_unlock - Clear a bit in memory, for unlock
 * @nr: the bit to set
 * @addr: the address to start counting from
 *
 * A weaker form of clear_bit_unlock() as used by __bit_lock_unlock(). If all
 * the bits in the word are protected by this lock some archs can use weaker
 * ops to safely unlock.
 *
 * See for example x86's implementation.
 */
static inline void
arch___clear_bit_unlock(unsigned int nr, volatile unsigned long *p)
{
	unsigned long old;

	p += BIT_WORD(nr);
	old = READ_ONCE(*p);
	old &= ~BIT_MASK(nr);
	raw_atomic_long_set_release((atomic_long_t *)p, old);

