/* 학습 해설
 * Lockref 표현·잠금과 count를 같은 CAS 범위에 넣기
 * 참조 수와 잠금 상태를 함께 관리하는 실제 구현을 읽고,CAS 최적화와 수명 종료 프로토콜의 조건을 배웁니다.
 * lockref는 spinlock과 int count를 한 구조에 둡니다. architecture의 CMPXCHG_LOCKREF 설정,SMP,SPINLOCK_SIZE<=4가 함께 성립하면 aligned_u64 lock_count와 lock/count 구조가 union으로 겹칩니다.8byte CAS로 lock 상태와 count를 함께 비교해 잠금 없이 변경하더라도 spinlock을 잡은 것과 양립하는 상태 조건을 확인합니다. 조건이 아니면 실제 spinlock 경로를 사용합니다.
 * 자료 표현과 target의 설정 및 spinlock 크기를 함께 확인합니다. 일반 atomic refcount와 같은 API라고 가정하지 않습니다. int count의 유효 범위와 객체 수명을 상위 사용자가 보장해야 합니다.
 */
struct lockref {
	union {
#if USE_CMPXCHG_LOCKREF
		aligned_u64 lock_count;
#endif
		struct {
			spinlock_t lock;
			int count;
		};
	};
};

extern void lockref_get(struct lockref *);
extern int lockref_put_return(struct lockref *);
extern int lockref_get_not_zero(struct lockref *);
extern int lockref_put_not_zero(struct lockref *);
extern int lockref_put_or_lock(struct lockref *);

extern void lockref_mark_dead(struct lockref *);
extern int lockref_get_not_dead(struct lockref *);

/* Must be called under spinlock for reliable results */
static inline bool __lockref_is_dead(const struct lockref *l)
{
	return ((int)l->count < 0);
}

