/* 학습 해설
 * Lockref get_not_zero·0과 dead를 함께 거절
 * 참조 수와 잠금 상태를 함께 관리하는 실제 구현을 읽고,CAS 최적화와 수명 종료 프로토콜의 조건을 배웁니다.
 * CAS 경로는 old.count<=0이면0을 반환하고 양수에서 성공하면1을 반환합니다. fallback도 spinlock 아래 count>0일 때만 증가시킵니다.0과 음수 dead 상태는 증가하지 않습니다. 반환은 새 count 숫자가 아니라 증가 성공 bool 입니다. 주소와 수명이 유효하다는 전제는 별도로 필요합니다.
 * 아직 살아 있는 양수 참조 집합에서 조건부 참조를 얻는 프로토콜에 사용합니다. 반환1 뒤에만 새 참조를 사용합니다. 실패0을 새 count가0이라는 유일한 뜻으로 해석하지 않습니다.
 */
int lockref_get_not_zero(struct lockref *lockref)
{
	int retval;

	CMPXCHG_LOOP(
		new.count++;
		if (old.count <= 0)
			return 0;
	,
		return 1;
	);

	spin_lock(&lockref->lock);
	retval = 0;
	if (lockref->count > 0) {
		lockref->count++;
		retval = 1;
	}
	spin_unlock(&lockref->lock);
	return retval;
}
EXPORT_SYMBOL(lockref_get_not_zero);

