/* 학습 해설
 * Lockref put_not_zero·마지막 참조를 남기는 감소
 * 참조 수와 잠금 상태를 함께 관리하는 실제 구현을 읽고,CAS 최적화와 수명 종료 프로토콜의 조건을 배웁니다.
 * old.count<=1이면 감소하지 않고0을 반환합니다. count>1이면 하나 감소하고1을 반환합니다. fallback은 spinlock 아래 같은 조건을 검사합니다. 이 API는 마지막 참조를0으로 만드는 해제 동작을 수행하지 않습니다. dead와0도 변화 없이 실패합니다.
 * 마지막 참조의 처리와 일반 감소를 나누는 상위 프로토콜에서 사용합니다. 실패하면 실제 현재 상태를 맞는 잠금 규약으로 확인합니다.0반환을 이미 감소가 완료됐다는 의미로 사용하지 않습니다.
 */
int lockref_put_not_zero(struct lockref *lockref)
{
	int retval;

	CMPXCHG_LOOP(
		new.count--;
		if (old.count <= 1)
			return 0;
	,
		return 1;
	);

	spin_lock(&lockref->lock);
	retval = 0;
	if (lockref->count > 1) {
		lockref->count--;
		retval = 1;
	}
	spin_unlock(&lockref->lock);
	return retval;
}
EXPORT_SYMBOL(lockref_put_not_zero);

